begin;

do $$
declare
  v_org_id constant uuid := '414a2e84-bc62-4c64-99ee-76db1cbc4654';

  v_test12_id constant uuid := '61d013e4-3b4b-5676-b39c-6d340f87b046';
  v_test12_version_id constant uuid := '74243315-ea1e-5178-83b8-d6077ab9dc59';
  v_test13_id constant uuid := '4f97740e-3f9e-559e-b120-cd043a42c755';
  v_test13_version_id constant uuid := '58b09fe5-2bc5-5803-ab0a-2a8834c85607';

  v_test14_id constant uuid := '85e10e1e-53f2-50a8-a128-ffac41e315ea';
  v_test14_version_id constant uuid := 'b502d8bb-5bef-5f7b-ab1d-daec88b95227';
  v_authoring_material_id constant uuid := '130fba32-2f3b-5f7c-9f1f-b34a3bd4cd78';
  v_authoring_version_id constant uuid := '93920ed9-2bfb-596c-8af6-3b3c4dfcfe91';
  v_fiat_normative_version_id constant uuid := 'dadf433e-5d7c-5373-b926-ed299332598f';

  v_count bigint;
begin
  /*
   * FASE 8A — Catálogo candidato do Teste 14 Fiat Comercial.
   * Mantém o teste e a versão em draft.
   * Limiares ficam fail-closed (100/100) até autorização explícita da política 85/90.
   * Não publica e não cria grants.
   */

  -- Guardas de baseline: Teste 12 Fiat regulatório e Teste 13 VW comercial seguem publicados.
  if not exists (
    select 1
    from public.assessment_tests t
    join public.assessment_test_versions v on v.test_id = t.id
    where t.id = v_test12_id
      and t.organization_id = v_org_id
      and t.code = 'regulamento_fiat_v1'
      and t.status = 'active'
      and v.id = v_test12_version_id
      and v.status = 'published'
      and v.passing_score = 90
      and v.legal_min_score = 90
  ) then
    raise exception 'FASE8A_ABORT: Teste 12 Fiat regulatório divergiu do baseline publicado 90/90.';
  end if;

  if not exists (
    select 1
    from public.assessment_tests t
    join public.assessment_test_versions v on v.test_id = t.id
    where t.id = v_test13_id
      and t.organization_id = v_org_id
      and t.code = 'consorcio_vw_comercial_v1'
      and t.status = 'active'
      and v.id = v_test13_version_id
      and v.status = 'published'
      and v.passing_score = 85
      and v.legal_min_score = 90
  ) then
    raise exception 'FASE8A_ABORT: Teste 13 VW comercial divergiu do baseline publicado 85/90.';
  end if;

  -- Fonte normativa Fiat aceita na governança 5E.
  if not exists (
    select 1
    from public.source_material_versions smv
    where smv.id = v_fiat_normative_version_id
      and smv.organization_id = v_org_id
      and smv.archived_at is null
      and smv.content_sha256 = '74ed3efacb7ee931839c51666c7617018d5f42afa6d06a1473adb7ac226f173a'
  ) then
    raise exception 'FASE8A_ABORT: fonte normativa Fiat V3 esperada não foi localizada ou o SHA-256 divergiu.';
  end if;

  -- Idempotência defensiva: o Teste 14 e sua fonte comercial ainda não podem existir.
  if exists (
    select 1
    from public.assessment_tests t
    where t.organization_id = v_org_id
      and (t.id = v_test14_id or t.code = 'consorcio_fiat_comercial_v1' or t.sequence_no = 14)
      and t.archived_at is null
  ) then
    raise exception 'FASE8A_ABORT: Teste 14, código consorcio_fiat_comercial_v1 ou sequence_no 14 já existe.';
  end if;

  if exists (
    select 1
    from public.source_materials sm
    where sm.organization_id = v_org_id
      and (sm.id = v_authoring_material_id or sm.code = 'teste14_fiat_comercial_rf')
      and sm.archived_at is null
  ) then
    raise exception 'FASE8A_ABORT: fonte de autoria comercial do Teste 14 já existe.';
  end if;

  -- As 6 competências regulatórias efetivamente usadas nesta versão devem existir.
  select count(*)
    into v_count
  from public.competency_domains cd
  where cd.organization_id = v_org_id
    and cd.archived_at is null
    and cd.id in (
      'dd860ec5-86b1-53cc-be5f-6ba5158f371a'::uuid,
      '4fcf7be5-4739-5de8-b52e-f19164f7e6c6'::uuid,
      'e7591bfd-4ff5-5e36-8661-b3a072cd9dff'::uuid,
      'c0534141-ebbf-5ff9-9bdd-ae8a91a48c01'::uuid,
      '87ba9d19-2195-5fb2-96d3-99a53cb7fb88'::uuid,
      'a31ceaeb-4651-592f-8fbf-f86a8d786a0c'::uuid
    );

  if v_count <> 6 then
    raise exception 'FASE8A_ABORT: esperava 6 competências regulatórias Fiat reutilizáveis; encontrado %.', v_count;
  end if;

  if exists (
    select 1
    from public.competency_domains cd
    where cd.organization_id = v_org_id
      and cd.code in (
        'fiat_com_produto_posicionamento',
        'fiat_com_planos_argumentacao',
        'fiat_com_pos_venda'
      )
      and cd.archived_at is null
