    raise exception 'FASE8A_ABORT: uma competência comercial Fiat do Teste 14 já existe.';
  end if;

  -- 3 competências comerciais específicas do material do Teste 14.
  insert into public.competency_domains (
    id, organization_id, code, sequence_no, name, description,
    domain_type, is_legal, default_weight, status, metadata
  )
  values
    ('fb0a69c0-b9bb-58d5-926b-da0e62bdfbbb'::uuid,'414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid,'fiat_com_produto_posicionamento',63,'Fiat Comercial — Produto e Posicionamento','Explicação comercial do consórcio, fundo comum, taxa de administração e diferenciação frente ao financiamento.','knowledge',false,0,'draft','{"test_number":14,"brand":"Consórcio Fiat","administrator":"Embracon","catalog_family":"commercial_regulatory","assessment_code":"consorcio_fiat_comercial_v1","commercial_layer":true,"modeling_phase":"8A","authoring_document":"Teste_14_Consorcio_Fiat_Versao_Comercial.md","homologation_status":"draft_candidate","assessment_version_code":"fiat-v3-comercial-v1","authoring_document_sha256":"a4b001b9a8694d4bec8fcf6d0a07310a72523fd37cd2598cf7bc81f3b8f070b2"}'::jsonb),
    ('9a71d296-8080-576b-902f-7364ad636e94'::uuid,'414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid,'fiat_com_planos_argumentacao',64,'Fiat Comercial — Planos e Argumentação','Explicação transparente dos planos Fiat/Embracon, redução de parcelas e antecipação de taxa de administração.','knowledge',false,0,'draft','{"test_number":14,"brand":"Consórcio Fiat","administrator":"Embracon","catalog_family":"commercial_regulatory","assessment_code":"consorcio_fiat_comercial_v1","commercial_layer":true,"modeling_phase":"8A","authoring_document":"Teste_14_Consorcio_Fiat_Versao_Comercial.md","homologation_status":"draft_candidate","assessment_version_code":"fiat-v3-comercial-v1","authoring_document_sha256":"a4b001b9a8694d4bec8fcf6d0a07310a72523fd37cd2598cf7bc81f3b8f070b2"}'::jsonb),
    ('c3b9174f-40ec-5458-a06e-c6d009c8c833'::uuid,'414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid,'fiat_com_pos_venda',65,'Fiat Comercial — Contemplação e Pós-venda','Orientação comercial sobre assembleias, disponibilização do crédito e acompanhamento após a contratação.','knowledge',false,0,'draft','{"test_number":14,"brand":"Consórcio Fiat","administrator":"Embracon","catalog_family":"commercial_regulatory","assessment_code":"consorcio_fiat_comercial_v1","commercial_layer":true,"modeling_phase":"8A","authoring_document":"Teste_14_Consorcio_Fiat_Versao_Comercial.md","homologation_status":"draft_candidate","assessment_version_code":"fiat-v3-comercial-v1","authoring_document_sha256":"a4b001b9a8694d4bec8fcf6d0a07310a72523fd37cd2598cf7bc81f3b8f070b2"}'::jsonb);

  -- Fonte comercial controlada e sua versão.
