    ('cedb34c9-7b46-54a3-be7b-93033889eb1a'::uuid,'414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid,'C','Informação importante para quem "trava" o uso do crédito','Regulamento do Contrato de Consórcio Fiat/Embracon — Cláusula 32',false,null,'{"test_number":14,"brand":"Consórcio Fiat","administrator":"Embracon","legal_scoring":true,"catalog_family":"commercial_regulatory","question_class":"REG","assessment_code":"consorcio_fiat_comercial_v1","question_number":23,"modeling_phase":"8A","criticality_basis":"no_critical_items_in_authoring_document","assessment_version_code":"fiat-v3-comercial-v1","authoring_document_sha256":"a4b001b9a8694d4bec8fcf6d0a07310a72523fd37cd2598cf7bc81f3b8f070b2","official_source_content_sha256":"74ed3efacb7ee931839c51666c7617018d5f42afa6d06a1473adb7ac226f173a"}'::jsonb),
    ('b51b3311-b4b7-5d86-8d3f-59829be8e3da'::uuid,'414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid,'B','Explique de forma simples: "o carro garante o próprio contrato"','Regulamento do Contrato de Consórcio Fiat/Embracon — Cláusula 33, §único',false,null,'{"test_number":14,"brand":"Consórcio Fiat","administrator":"Embracon","legal_scoring":true,"catalog_family":"commercial_regulatory","question_class":"REG","assessment_code":"consorcio_fiat_comercial_v1","question_number":24,"modeling_phase":"8A","criticality_basis":"no_critical_items_in_authoring_document","assessment_version_code":"fiat-v3-comercial-v1","authoring_document_sha256":"a4b001b9a8694d4bec8fcf6d0a07310a72523fd37cd2598cf7bc81f3b8f070b2","official_source_content_sha256":"74ed3efacb7ee931839c51666c7617018d5f42afa6d06a1473adb7ac226f173a"}'::jsonb),
    ('7aed79ed-1c48-50c8-9d5e-1f2b9d99f3c0'::uuid,'414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid,'B','Ajuda o cliente a entender o cronograma até a entrega do carro','Regulamento do Contrato de Consórcio Fiat/Embracon — Cláusula 34',false,null,'{"test_number":14,"brand":"Consórcio Fiat","administrator":"Embracon","legal_scoring":true,"catalog_family":"commercial_regulatory","question_class":"REG","assessment_code":"consorcio_fiat_comercial_v1","question_number":25,"modeling_phase":"8A","criticality_basis":"no_critical_items_in_authoring_document","assessment_version_code":"fiat-v3-comercial-v1","authoring_document_sha256":"a4b001b9a8694d4bec8fcf6d0a07310a72523fd37cd2598cf7bc81f3b8f070b2","official_source_content_sha256":"74ed3efacb7ee931839c51666c7617018d5f42afa6d06a1473adb7ac226f173a"}'::jsonb),
    ('7a0a6eb2-98b0-5223-86a7-b9102b491df8'::uuid,'414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid,'B','Custo que o cliente precisa saber antes de tentar repassar a cota','Regulamento do Contrato de Consórcio Fiat/Embracon — Cláusula 37',false,null,'{"test_number":14,"brand":"Consórcio Fiat","administrator":"Embracon","legal_scoring":true,"catalog_family":"commercial_regulatory","question_class":"REG","assessment_code":"consorcio_fiat_comercial_v1","question_number":26,"modeling_phase":"8A","criticality_basis":"no_critical_items_in_authoring_document","assessment_version_code":"fiat-v3-comercial-v1","authoring_document_sha256":"a4b001b9a8694d4bec8fcf6d0a07310a72523fd37cd2598cf7bc81f3b8f070b2","official_source_content_sha256":"74ed3efacb7ee931839c51666c7617018d5f42afa6d06a1473adb7ac226f173a"}'::jsonb),
    ('24f823af-016d-5980-a024-6125885c5cdd'::uuid,'414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid,'B','Alerta importante contra "venda informal" de cota, que gera problema depois','Regulamento do Contrato de Consórcio Fiat/Embracon — Cláusula 37, §6',false,null,'{"test_number":14,"brand":"Consórcio Fiat","administrator":"Embracon","legal_scoring":true,"catalog_family":"commercial_regulatory","question_class":"REG","assessment_code":"consorcio_fiat_comercial_v1","question_number":27,"modeling_phase":"8A","criticality_basis":"no_critical_items_in_authoring_document","assessment_version_code":"fiat-v3-comercial-v1","authoring_document_sha256":"a4b001b9a8694d4bec8fcf6d0a07310a72523fd37cd2598cf7bc81f3b8f070b2","official_source_content_sha256":"74ed3efacb7ee931839c51666c7617018d5f42afa6d06a1473adb7ac226f173a"}'::jsonb),
    ('3046938a-ef05-5ef7-b717-ab796f935d31'::uuid,'414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid,'B','Argumento forte para reforçar a importância da regularidade dos pagamentos','Regulamento do Contrato de Consórcio Fiat/Embracon — Cláusula 39',false,null,'{"test_number":14,"brand":"Consórcio Fiat","administrator":"Embracon","legal_scoring":true,"catalog_family":"commercial_regulatory","question_class":"REG","assessment_code":"consorcio_fiat_comercial_v1","question_number":28,"modeling_phase":"8A","criticality_basis":"no_critical_items_in_authoring_document","assessment_version_code":"fiat-v3-comercial-v1","authoring_document_sha256":"a4b001b9a8694d4bec8fcf6d0a07310a72523fd37cd2598cf7bc81f3b8f070b2","official_source_content_sha256":"74ed3efacb7ee931839c51666c7617018d5f42afa6d06a1473adb7ac226f173a"}'::jsonb),
    ('061e4869-46d3-5df1-b5ab-2ead48300b0f'::uuid,'414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid,'B','Seja transparente sobre isso já na venda, evita reclamação na exclusão','Regulamento do Contrato de Consórcio Fiat/Embracon — Cláusula 40',false,null,'{"test_number":14,"brand":"Consórcio Fiat","administrator":"Embracon","legal_scoring":true,"catalog_family":"commercial_regulatory","question_class":"REG","assessment_code":"consorcio_fiat_comercial_v1","question_number":29,"modeling_phase":"8A","criticality_basis":"no_critical_items_in_authoring_document","assessment_version_code":"fiat-v3-comercial-v1","authoring_document_sha256":"a4b001b9a8694d4bec8fcf6d0a07310a72523fd37cd2598cf7bc81f3b8f070b2","official_source_content_sha256":"74ed3efacb7ee931839c51666c7617018d5f42afa6d06a1473adb7ac226f173a"}'::jsonb),
    ('a0b870a9-cfef-5419-b7ab-235d5de3043b'::uuid,'414a2e84-bc62-4c64-99ee-76db1cbc4654'::uuid,'D','Informação de suporte pós-venda / relacionamento de longo prazo','Regulamento do Contrato de Consórcio Fiat/Embracon — Cláusula 43.4',false,null,'{"test_number":14,"brand":"Consórcio Fiat","administrator":"Embracon","legal_scoring":true,"catalog_family":"commercial_regulatory","question_class":"REG","assessment_code":"consorcio_fiat_comercial_v1","question_number":30,"modeling_phase":"8A","criticality_basis":"no_critical_items_in_authoring_document","assessment_version_code":"fiat-v3-comercial-v1","authoring_document_sha256":"a4b001b9a8694d4bec8fcf6d0a07310a72523fd37cd2598cf7bc81f3b8f070b2","official_source_content_sha256":"74ed3efacb7ee931839c51666c7617018d5f42afa6d06a1473adb7ac226f173a"}'::jsonb);

  /*
   * PÓS-CONDIÇÕES
   */

  if not exists (
    select 1
    from public.assessment_tests t
    join public.assessment_test_versions v on v.test_id = t.id
    where t.id = v_test14_id
      and t.organization_id = v_org_id
      and t.code = 'consorcio_fiat_comercial_v1'
      and t.sequence_no = 14
      and t.status = 'draft'
      and t.question_count = 30
      and v.id = v_test14_version_id
      and v.version_no = 1
      and v.version_code = 'fiat-v3-comercial-v1'
      and v.status = 'draft'
      and v.passing_score = 100
      and v.legal_min_score = 100
      and v.metadata ->> 'approval_policy_status' = 'pending_authorization'
  ) then
    raise exception 'FASE8A_ABORT: pós-condição de identidade/status fail-closed do Teste 14 falhou.';
  end if;

  select count(*) into v_count
  from public.assessment_version_questions avq
  where avq.test_version_id = v_test14_version_id
    and avq.archived_at is null;
  if v_count <> 30 then
    raise exception 'FASE8A_ABORT: esperava 30 vínculos de questões; encontrado %.', v_count;
  end if;

  select count(*) into v_count
  from public.assessment_question_options o
  join public.assessment_version_questions avq on avq.question_id = o.question_id
  where avq.test_version_id = v_test14_version_id
    and avq.archived_at is null
    and o.archived_at is null;
  if v_count <> 120 then
    raise exception 'FASE8A_ABORT: esperava 120 alternativas; encontrado %.', v_count;
  end if;

  select count(*) into v_count
  from private.assessment_question_keys k
  join public.assessment_version_questions avq on avq.question_id = k.question_id
  where avq.test_version_id = v_test14_version_id
    and avq.archived_at is null;
  if v_count <> 30 then
    raise exception 'FASE8A_ABORT: esperava 30 gabaritos privados; encontrado %.', v_count;
  end if;

  select count(*) into v_count
  from public.assessment_version_questions avq
  join public.assessment_questions q on q.id = avq.question_id
  where avq.test_version_id = v_test14_version_id
    and avq.archived_at is null
    and q.metadata ->> 'question_class' = 'COM'
    and coalesce((q.metadata ->> 'legal_scoring')::boolean, false) = false;
  if v_count <> 10 then
    raise exception 'FASE8A_ABORT: esperava 10 questões COM; encontrado %.', v_count;
  end if;

  select count(*) into v_count
  from public.assessment_version_questions avq
  join public.assessment_questions q on q.id = avq.question_id
  where avq.test_version_id = v_test14_version_id
    and avq.archived_at is null
    and q.metadata ->> 'question_class' = 'REG'
    and coalesce((q.metadata ->> 'legal_scoring')::boolean, false) = true;
  if v_count <> 20 then
    raise exception 'FASE8A_ABORT: esperava 20 questões REG com legal_scoring=true; encontrado %.', v_count;
  end if;

  select count(*) into v_count
  from public.assessment_version_sources avs
  where avs.test_version_id = v_test14_version_id
    and avs.archived_at is null
    and avs.is_required = true;
  if v_count <> 2 then
    raise exception 'FASE8A_ABORT: esperava 2 fontes obrigatórias; encontrado %.', v_count;
  end if;

  -- Cada gabarito precisa apontar para uma alternativa realmente existente.
  select count(*) into v_count
  from private.assessment_question_keys k
  join public.assessment_version_questions avq on avq.question_id = k.question_id
  left join public.assessment_question_options o
    on o.question_id = k.question_id
   and o.option_code = k.correct_option_code
   and o.archived_at is null
  where avq.test_version_id = v_test14_version_id
    and avq.archived_at is null
    and o.id is null;
  if v_count <> 0 then
    raise exception 'FASE8A_ABORT: existem % gabaritos sem alternativa correspondente.', v_count;
  end if;

  -- Catálogo candidato não pode criar liberação.
  select count(*) into v_count
  from private.assessment_test_access_grants g
  where g.organization_id = v_org_id
    and g.test_id = v_test14_id
    and g.archived_at is null;
  if v_count <> 0 then
    raise exception 'FASE8A_ABORT: catálogo do Teste 14 criou % grants indevidos.', v_count;
  end if;

  -- Controles: Testes 12 e 13 continuam publicados.
  if not exists (
    select 1 from public.assessment_tests t
    join public.assessment_test_versions v on v.test_id=t.id
    where t.id=v_test12_id and t.status='active'
      and v.id=v_test12_version_id and v.status='published'
      and v.passing_score=90 and v.legal_min_score=90
  ) then
    raise exception 'FASE8A_ABORT: controle do Teste 12 foi alterado.';
  end if;

  if not exists (
    select 1 from public.assessment_tests t
    join public.assessment_test_versions v on v.test_id=t.id
    where t.id=v_test13_id and t.status='active'
      and v.id=v_test13_version_id and v.status='published'
      and v.passing_score=85 and v.legal_min_score=90
  ) then
    raise exception 'FASE8A_ABORT: controle do Teste 13 foi alterado.';
  end if;
end
$$;

commit;
